#!/usr/bin/env python3
"""Prepare Unit 2 curriculum records from captured metadata; no network/database access."""
import json,hashlib,pathlib,sys,uuid
w=pathlib.Path(sys.argv[1]);read=lambda n:json.loads((w/n).read_text())
canonical=lambda v:json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':'))
digest=lambda v:hashlib.sha256(canonical(v).encode()).hexdigest()
identity=lambda k:str(uuid.uuid5(uuid.NAMESPACE_URL,'https://www.haiedu.am/curriculum/'+k))
save=lambda n,v:(w/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
i=read('inventory.json');r=i['release'];rid=r['id'];unit=i['releaseUnits'][0]['unit_id'];binding=i['sourceBindings'][0]
assert r['status']=='draft' and r['reconciliation_id'] is None and i['topics'] is None
assert len(i['skills'])==len(i['releaseSkills'])==15 and len(i['families'])==192
assert all(s['outcome_mapping_snapshot']==[] for s in i['releaseSkills'])
skills={s['code'][-3:]:s for s in i['skills']};assert set(skills)=={f'S{n:02}'for n in range(1,16)}
assert len({f['id']for f in i['families']})==192
assert all(f['skill_id'] in {skills[f'S{n:02}']['id']for n in range(1,14)} for f in i['families'])
